fn to_hex(bytes: &[u8]) -> String {
	if bytes.is_empty() {
		"".into()
	} else {
		bytes.iter().map(|x| format!("-{:02X}", x)).collect::<String>()[1..].to_string()
	}
}

fn to_hex_proper(bytes: &[u8]) -> String {
	if bytes.is_empty() {
		"".into()
	} else {
		bytes.iter().rev().map(|x| format!("{:02X}", x)).collect::<String>()[1..].to_string()
	}
}

fn parse_tl(tl: &str) -> Vec<(&str, &str)> {
	let mut pairs = Vec::new();
	let mut cur_jp = None;
	let mut cur_tl = None;
	for line in tl.lines() {
		if line.is_empty() {
			pairs.push((cur_jp.take().unwrap(), cur_tl.take().unwrap()));
		} else if cur_jp.is_none() {
			cur_jp = Some(line);
		} else if cur_tl.is_none() {
			cur_tl = Some(line);
		}
	}
	if cur_tl.is_some() {
		pairs.push((cur_jp.take().unwrap(), cur_tl.take().unwrap()));
	}
	pairs
}

macro_rules! emitln {
	($($arg:expr),*) => {
		writeln!($($arg),*).unwrap()
	};
}

static UNIMPL: LazyLock<RwLock<HashMap<String, String>>> = LazyLock::new(|| RwLock::new(HashMap::new()));

fn run(name: &str, tl_raw: Option<&str>, language: &str, is_end: bool) {
	println!("processing {name} into language {language}");
	let tl = tl_raw.map(|x| parse_tl(x));
	let scr_bytes = std::fs::read(format!("decompressed/{}.SCN", name.to_uppercase())).unwrap();
	let mut buf = ByteBuffer::from_bytes(&scr_bytes);
	let mut txt = String::new();
	let mut dec = String::new();
	//let header_size = buf.read_u8().unwrap();
	//println!("header {} bytes", header_size);
	//buf.set_rpos(header_size as usize);
	let mut tl_idx = 0;
	//println!("{:04X}", SPRITE_NAMES.iter().position(|x| x == &"YU03CA").unwrap());
	assert_eq!(SPRITE_NAMES[0x42E], "YU03CA");
	let mut last_line_ends_with_newline = true;
	let mut last_cmd_was_line = false;
	let mut text_id = 0;
	let mut read_file = 0;
	loop {
		let off = buf.get_rpos();
		let opcode = buf.read_u8().unwrap();
		if opcode == 0xFF {
			break;
		}
		if OPCODE_METAS_BYTES.get(opcode as usize * 0x18..).is_none() {
			break;
		}
		let full_len = u32::from_le_bytes(OPCODE_METAS_BYTES[opcode as usize * 0x18..][..4].try_into().unwrap());
		let name = opcode.to_string();
		let name = *OPCODE_NAMES.get(opcode as usize).unwrap_or(&name.as_str());
		let args = buf.read_bytes(full_len as usize - 1).unwrap();
		if name != "msg_disp2" {
			//assert!(last_line_ends_with_newline);
		}
		match name {
			"msg_disp2" => {
				let msg_pos = u32::from_le_bytes(args[3..3 + 4].try_into().unwrap());
				let mut msg_end = msg_pos;
				while scr_bytes[msg_end as usize] != 0 {
					msg_end += 1;
				}
				let msg = SHIFT_JIS.decode(&scr_bytes[msg_pos as usize..msg_end as usize]).0.to_string().replace("～", "〜");
				if let Some(tl) = &tl {
					if let Some(x) = msg.strip_prefix(tl[tl_idx].0) {
						let tled = if x == "%K%P" {
								format!("{}\n", tl[tl_idx].1)
							} else {
								format!("{}{}", tl[tl_idx].1, x)
							}.replace("%K%P", "\n{textColor 0 2}")
							.replace("%K", "{textColor 0 2}")
							.replace("%N", "  ")
							.replace("Yuka: \"", "【Yuka】 \"")
							.replace("Haruka: \"", "【Haruka】 \"")
							.replace("Makoto: \"", "【Makoto】 \"")
							.replace("Kurumi: \"", "【Kurumi】 \"")
							.replace("Izumi: \"", "【Izumi】 \"")
							.replace("Okuhiko: \"", "【Okuhiko】 \"")
							.replace("Okuhiko: (", "【Okuhiko】 (")
							.replace("優夏「", "【優夏】  「")
							.replace("遙「", "【遙】  「")
							.replace("億彦「", "【億彦】  「")
							.replace("億彦（", "【億彦】  （")
							.replace("%T030", "{delay 30}")
							.replace("%T060", "{delay 60}")
							.replace("%W", "{delay 5}");
						emitln!(txt, "&{off:04X}: {}.{} {}-Z-{} @{}", name, full_len, to_hex(&args[..3]), to_hex(&args[3 + 4..]), format!("{}{}", tled, x));
						if last_line_ends_with_newline {
							emitln!(&mut dec, "[00000000] 10: text {:02x}", text_id);
							text_id += 1;
						}
						emitln!(dec, "{{textColor 0 2}}{}", tled);
						last_line_ends_with_newline = tled.ends_with('\n');
					} else {
						panic!("what!? \"{}\"\n!=     \"{}\"", msg, tl[tl_idx].0);
					}
				} else {
					emitln!(txt, "{}.{} {}-Z-{} @{}", name, full_len, to_hex(&args[..3]), to_hex(&args[3 + 4..]), msg);
					let tled = if let Some(msg) = msg.strip_suffix("%K%P") {
							format!("{}\n", msg)
						} else {
							msg
						}.replace("%K%P", "\n{textColor 0 2}")
						.replace("%K", "{textColor 0 2}")
						.replace("%N", "  ")
						.replace("Yuka: \"", "【Yuka】 \"")
						.replace("Haruka: \"", "【Haruka】 \"")
						.replace("Makoto: \"", "【Makoto】 \"")
						.replace("Kurumi: \"", "【Kurumi】 \"")
						.replace("Izumi: \"", "【Izumi】 \"")
						.replace("Okuhiko: \"", "【Okuhiko】 \"")
						.replace("Okuhiko: (", "【Okuhiko】 (")
						.replace("優夏「", "【優夏】  「")
						.replace("遙「", "【遙】  「")
						.replace("億彦「", "【億彦】  「")
						.replace("億彦（", "【億彦】  （")
						.replace("%T030", "{delay 30}")
						.replace("%T060", "{delay 60}")
						.replace("%W", "{delay 5}");
					emitln!(txt, "&{off:04X}: {}.{} {}-Z-{} @{}", name, full_len, to_hex(&args[..3]), to_hex(&args[3 + 4..]), tled);
					if last_line_ends_with_newline {
						emitln!(dec, "[00000000] 10: text {:02x}", text_id);
						text_id += 1;
					}
					emitln!(dec, "{{textColor 0 2}}{}", tled);
					last_line_ends_with_newline = tled.ends_with('\n');
				}
				tl_idx += 1;
			}
			"graph_disp" | "graph_disp_ex" => {
				let mut msg_pos = u32::from_le_bytes(args[3..3 + 4].try_into().unwrap());
				let mut msg_end = msg_pos + 12;
				let mut graph_objs = String::new();
				let mut cmt = String::new();
				//while SCR_BYTES[msg_end as usize] != 0 {
				//	msg_end += 1;
				//}
				//println!("since last {}", msg_pos - last_g);
				let graph_obj = &scr_bytes[msg_pos as usize..msg_end as usize];
				let img_idx = graph_obj[4] as usize | ((graph_obj[5] as usize & 0xF) << 8);
				let img_name = match graph_obj[5] >> 4 {
					1 => BG_NAMES[img_idx],
					2 => EV_NAMES[img_idx],
					3 => if img_idx == 0xFFF {
						"~"
					} else {
						SPRITE_NAMES[img_idx]
					},
					x => panic!("omaga {:X}", x)
				};
				if graph_obj[0] == 0 {
					cmt = format!("{} #bg {}", cmt, img_name);
					if img_name == "BG_00" {
						emitln!(dec, "[00000000] 10: removeBG 0 0 0");
					} else if img_name == "BG_01" {
						emitln!(dec, "[00000000] 10: removeBG 1 0 0");
					} else {
						emitln!(dec, "[00000000] 10: bgload 00000000 {} 0 1", match img_name {
							"BG900" => "fullwin",
							"BG901" => "fullwin", // supposed to be a monochrome version of it
							img_name => img_name
						});
					}
				} else if graph_obj[0] == 1 || graph_obj[0] == 3 {
					let mut sprite_pos_id = graph_obj[9];
					let sprite_slot_id = graph_obj[0];
					cmt = format!("{} #sprite {} pos:{} slot:{}", cmt, img_name, sprite_pos_id, sprite_slot_id);
					if img_name == "CALEN1" {
						emitln!(dec, "[00000000] 10: varop VAR_(28_0a)_a0_fb (14) := (00) 1");
						emitln!(dec, "[00000000] 10: varop VAR_(28_0a)_a0_fe (14) := (00) 1");
						emitln!(dec, "[00000000] 10: dayIntro 00000000 BGCAL1.cps");
					} else if img_name == "CALEN2" {
						emitln!(dec, "[00000000] 10: varop VAR_(28_0a)_a0_fb (14) := (00) 2");
						emitln!(dec, "[00000000] 10: varop VAR_(28_0a)_a0_fe (14) := (00) 2");
						emitln!(dec, "[00000000] 10: dayIntro 00000000 BGCAL2.cps");
					} else if img_name == "CALEN3" {
						emitln!(dec, "[00000000] 10: varop VAR_(28_0a)_a0_fb (14) := (00) 3");
						emitln!(dec, "[00000000] 10: varop VAR_(28_0a)_a0_fe (14) := (00) 3");
						emitln!(dec, "[00000000] 10: dayIntro 00000000 BGCAL3.cps");
					} else if img_name == "~" {
						if args[0] > 1 {
							emitln!(dec, "[00000000] 10: removeAllFG 3");
						} else {
							emitln!(dec, "[00000000] 10: removeFG 0 3");
						}
					} else if args[0] > 1 {
						let obj2 = &scr_bytes[msg_end as usize..msg_end as usize + 12];
						let img2_idx = obj2[4] as usize | ((obj2[5] as usize & 0xF) << 8);
						let img2_name = match obj2[5] >> 4 {
							3 => if img2_idx == 0xFFF {
								panic!("cannot be sprite removal")
							} else {
								SPRITE_NAMES[img2_idx]
							},
							x => panic!("expected sprite, {:X}", x)
						};
						let sprite2_slot_id = obj2[0];
						emitln!(dec, "[00000000] 11: multifgload2 00000000 {} {} 00000000 {} {}",
							img_name, sprite_slot_id,
							img2_name, sprite2_slot_id);
					} else {
						// sprite pos in N7 PSP format:
						// 0: middle
						// 1: left
						// else: right
						// sprite pos in N7E dec format:
						// 1: middle
						// 2: left
						// else: right
						sprite_pos_id = if graph_obj[3] == 0 {
							1
						} else {
							match sprite_pos_id {
								0 => 2,
								1 => 0,
								_ => 1
							}
						};
						emitln!(dec, "[00000000] 11: fgload {} 00000000 {} {} 3", sprite_slot_id, img_name, sprite_pos_id);
					}
				}
				for _ in 0..args[0] {
					graph_objs = format!("{} ${}$", graph_objs, to_hex(graph_obj));
				}
				emitln!(txt, "&{off:04X}: {}.{} {}-G{}{}", name, full_len, to_hex(&args[..3]), graph_objs, cmt);
				//println!("{}.{} {}-Z @{}", name, full_len, to_hex(&args[..3]), std::str::from_utf8(msg).unwrap());
			}
			"graph_pos" => {
				let mut cmt = String::new();
				if args[0] == 1 || args[0] == 3 {
					emitln!(dec, "[00000000] 10: moveFG {} {}", args[0], match args[3] {
						0 => 2,
						1 => 0,
						_ => 1
					});
					cmt = format!(" # fgmove {} {}", args[0], args[3]);
				}
				emitln!(txt, "&{off:04X}: {}.{} {}{}", name, full_len, to_hex(&args), cmt);
			}
			"file_read" => {
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
				read_file = args[1];
			}
			"se_set" => {
				if args[0] == 0 {
					emitln!(dec, "[00000000] 10: playSFX {} 1\n", SE_NAMES[read_file as usize]);
				} else {
					emitln!(dec, "[00000000] 10: playBGM {}\n", read_file - 103);
				}
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"se_del" => {
				if args[0] == 0 {
					emitln!(dec, "[00000000] 10: stopSFX");
				} else {
					emitln!(dec, "[00000000] 10: stopBGM");
				}
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"se_wait" => {
				if args[0] == 0 && args[1] == 2 {
					emitln!(dec, "[00000000] 10: waitForSFX");
				} else {
					// probably just meant to wait for the bgm to load?
				}
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"time_wait" => {
				emitln!(dec, "[00000000] 10: delay {}", u16::from_le_bytes(args[1..].try_into().unwrap()));
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"effect_start" => {
				emitln!(dec, "[00000000] 10: cmd1 32");
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"effect_wait" => {
				if args[1] == 0xFC {
					emitln!(dec, "[00000000] 10: cmd2 13");
				}
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"fade_start" => {
				if args[0] == 0x82 {
					emitln!(dec, "[00000000] 10: removeBG 0 1 1");
				} else if args[0] == 0x80 {
					if args[1] == 1 {
						emitln!(dec, "[00000000] 10: fadetowhite");
					} else {
						emitln!(dec, "[00000000] 10: fadetoblack");
					}
				} else if args[0] == 0x7F {
					emitln!(dec, "[00000000] 10: fadein");
				}
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			"msg_clear" => {
				emitln!(dec, "[00000000] 10: cmd24");
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
			}
			_ => {
				emitln!(txt, "&{off:04X}: {}.{} {}", name, full_len, to_hex(&args));
				if name == "end" {
					emitln!(dec, "[00000000] 10: returnTitle");
					break;
				} else {
					let s = format!("{}.{}", name, full_len);
					let mut unimpl = UNIMPL.write().unwrap();
					if !unimpl.contains_key(&s) {
						unimpl.insert(s, format!("{}.{} {}", name, full_len, to_hex(&args)));
					}
				}
			}
		}
	}
	std::fs::create_dir_all(format!("out_{language}")).unwrap();
	if is_end {
		emitln!(dec, "[00000000] 10: appendstoryend {name}");
	}
	std::fs::write(format!("out_{language}/{name}.dec"), dec).unwrap();
	std::fs::write(format!("out_{language}/{name}.txt"), txt).unwrap();
}

fn main() {
	run("user08", None, "ja", true);
	run("user08", Some(include_str!("../user08.en.tl.txt")), "en", true);

	run("user20a", None, "ja", false);
	run("user20a", Some(include_str!("../user20a.en.tl.txt")), "en", false);

	run("user20b", None, "ja", false);
	run("user20b", Some(include_str!("../user20b.en.tl.txt")), "en", false);

	println!("unimplemented commands found: {:#?}", UNIMPL.read().unwrap().values());
}
